do $$ declare a uuid;b uuid;sid bigint;gid bigint;begin select id into a from auth.users order by created_at limit 1;select id into b from auth.users order by created_at offset 1 limit 1;if a is null or b is null then return;end if;insert into public.squads(name,subtitle,created_by) values('Seed Focus','Dados sintéticos locais',a) returning id into sid;insert into public.squad_members values(sid,a),(sid,b) on conflict do nothing;insert into public.daily_tasks(user_id,title,category,task_date,done,done_at) values(a,'Revisar SQL','estudo',current_date,true,now()),(b,'Ler documentação','estudo',current_date,false,null);insert into public.goals(user_id,category,title,progress) values(a,'estudo','Concluir Sprint 1',0.5) returning id into gid;insert into public.check_ins(user_id,check_date,minutes) values(a,current_date,45) on conflict do nothing;insert into public.points_events(user_id,source,ref_id,points) select a,'check_in',id,10 from public.check_ins where user_id=a and check_date=current_date on conflict do nothing;end $$;
